import java.util.Scanner;

public class Main {
    private static long higherDividend(long x, long divider) {
        if (x % divider == 0)
            return x;
        if (x < divider)
            return 0;
        long left = x - divider;
        long right = x;
        long middle = (left + right) / 2;
        while (middle % divider != 0) {
            if (middle / divider < x / divider)
                left = middle;
            else
                right = middle;
            middle = (left + right) / 2;
        }
        return middle;
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        long cnt1 = scanner.nextLong();
        long cnt2 = scanner.nextLong();
        long x = scanner.nextLong();
        long y = scanner.nextLong();

        long count = 0;
        long barrier = cnt1 + cnt2;
        while (count != cnt1 + cnt2) {
            long bad = higherDividend(barrier, x * y) / (x * y);
            long xCountCommon = higherDividend(barrier, y) / y - bad;
            long yCountCommon = higherDividend(barrier, x) / x - bad;
            long xCount = Math.min(xCountCommon, cnt1);
            long yCount = Math.min(yCountCommon, cnt2);
            if (xCount < xCountCommon)
                bad += xCountCommon - xCount;
            if (yCount < yCountCommon)
                bad += yCountCommon - yCount;
            long good = barrier - bad - xCount - yCount;
            count = good + xCount + yCount;
            barrier += cnt1 + cnt2 - count;
        }

        System.out.print(barrier);
    }
}

