            var cnt2 = long.Parse(input[1]);
            var x = long.Parse(input[2]);
            var y = long.Parse(input[3]);

            long count = 0;
            long barrier = cnt1 + cnt2;
            while (count != cnt1 + cnt2)
            {
                long bad = HigherDividend(barrier, x*y)/(x*y);
                long xCountCommon = HigherDividend(barrier, y) / y - bad;
                long yCountCommon = HigherDividend(barrier, x) / x - bad;
                long xCount = Math.Min(xCountCommon, cnt1);
                long yCount = Math.Min(yCountCommon, cnt2);
                if (xCount < xCountCommon)
                    bad += xCountCommon - xCount;
                if (yCount < yCountCommon)
                    bad += yCountCommon - yCount;
                long good = barrier - bad - xCount - yCount;
                count = good + xCount + yCount;
                barrier += cnt1 + cnt2 - count;
            }

            Console.Write(barrier);
        }
    }
}
